import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Sequence, Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.0003, 'dropout_rate': 0.1,
        'd_model': 256, 'num_blocks': 5, 'dilations': [1,2,4,8,16], 'kernel_size': 7,
        'transformer_layers': 4, 'num_heads': 4, 'transformer_ff_dim': 512
    }

# --- DSConv Backbone (from SOTA) ---
class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int = 7; dilation: int = 1; dropout_rate: float = 0.1
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h = nn.gelu(h); h = nn.Conv(features=self.d_model, kernel_size=(1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class DSConvFeatureExtractor(nn.Module):
    d_model: int; num_blocks: int; dilations: Sequence[int]; kernel_size: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.Dense(self.d_model)(x); h = nn.gelu(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        for i in range(self.num_blocks):
            d = self.dilations[i] if i < len(self.dilations) else self.dilations[-1]
            h = DSConvDilatedBlock(self.d_model, self.kernel_size, d, self.dropout_rate)(h, deterministic=deterministic)
        return h

# --- Transformer Aggregator Components (Learned from Axiom I and my failure) ---
class AddPositionalEncodings(nn.Module):
    d_model: int
    @nn.compact
    def __call__(self, x):
        seq_len = x.shape[1]
        position = jnp.arange(seq_len)[:, jnp.newaxis]
        div_term = jnp.exp(jnp.arange(0, self.d_model, 2) * -(jnp.log(10000.0) / self.d_model))
        pe = jnp.zeros((seq_len, self.d_model))
        pe = pe.at[:, 0::2].set(jnp.sin(position * div_term))
        pe = pe.at[:, 1::2].set(jnp.cos(position * div_term))
        return x + pe[jnp.newaxis, :, :]

class TransformerEncoderBlock(nn.Module):
    d_model: int; num_heads: int; ff_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.MultiHeadDotProductAttention(num_heads=self.num_heads, qkv_features=self.d_model, dropout_rate=self.dropout_rate)(h, deterministic=deterministic)
        x = x + nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        h = nn.LayerNorm()(x)
        h = nn.Dense(features=self.ff_dim)(h); h = nn.gelu(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        h = nn.Dense(features=self.d_model)(h)
        x = x + nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x

# --- Main Hybrid Network ---
class DSConvTransformerNet(nn.Module):
    d_output: int; task_type: str; d_model: int; num_blocks: int; dilations: Sequence[int]
    kernel_size: int; dropout_rate: float; transformer_layers: int; num_heads: int; transformer_ff_dim: int
    @nn.compact
    def __call__(self, x, deterministic=True):
        features_seq = DSConvFeatureExtractor(d_model=self.d_model, num_blocks=self.num_blocks, dilations=self.dilations,
                                              kernel_size=self.kernel_size, dropout_rate=self.dropout_rate)(x, deterministic=deterministic)

        cls_token = self.param('cls', nn.initializers.zeros, (1, 1, self.d_model))
        cls_token = jnp.tile(cls_token, (features_seq.shape[0], 1, 1))
        h = jnp.concatenate([cls_token, features_seq], axis=1)

        h = AddPositionalEncodings(d_model=self.d_model)(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)

        for _ in range(self.transformer_layers):
            h = TransformerEncoderBlock(d_model=self.d_model, num_heads=self.num_heads, ff_dim=self.transformer_ff_dim, dropout_rate=self.dropout_rate)(h, deterministic=deterministic)

        agg_vec = h[:, 0] # Use the CLS token for aggregation

        logits = nn.Dense(self.d_output)(agg_vec)
        return logits.squeeze(-1) if self.task_type == 'regression' and self.d_output == 1 else logits

class NetworkWrapper:
    def __init__(self, model_instance): self.network = model_instance
    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        return self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
    def apply(self, params, x, deterministic=True, rng_key=None):
        if rng_key is None: rng_key = random.PRNGKey(0)
        return self.network.apply(params, x, deterministic=deterministic, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    model = DSConvTransformerNet(d_output=hparams.get("d_output"), task_type=hparams.get("task_type"), d_model=hparams.get("d_model"), 
                               num_blocks=hparams.get("num_blocks"), dilations=hparams.get("dilations"),
                               kernel_size=hparams.get("kernel_size"), dropout_rate=hparams.get("dropout_rate"),
                               transformer_layers=hparams.get("transformer_layers"), num_heads=hparams.get("num_heads"),
                               transformer_ff_dim=hparams.get("transformer_ff_dim"))
    return NetworkWrapper(model)
